// BUG-001: Cart badge is not updated after removing an item
//
// Generated by EXEGEZIS 0.1.0 from test plan BUG-001 (sha256:0513d70002d5…).
// Do not edit by hand. Regenerate with: exegezis compile --plan benchmarks/buggy-shop/cases/BUG-001/plan.json
// Standalone: it needs only @playwright/test. Run it with:
//   npx playwright test BUG-001.spec.ts
// Target: http://localhost:3000/ (override with the BASE_URL environment variable).
//
// Preconditions:
//   - buggy-shop is running at the target URL
//   - Every execution starts from a fresh browser context, hence a new session with an empty cart

import { expect, test, type Response } from "@playwright/test";

test.use({
  baseURL: process.env["BASE_URL"] ?? "http://localhost:3000/",
  viewport: { width: 1280, height: 720 },
  locale: "en-US",
  timezoneId: "UTC",
  actionTimeout: 10000,
  navigationTimeout: 30000,
});

test("BUG-001: Cart badge is not updated after removing an item", async ({ page }) => {
  test.setTimeout(120000);

  // Responses observed during the test, for HTTP assertions.
  const responses: Response[] = [];
  page.on("response", (response) => responses.push(response));

  await test.step("1. navigate /", async () => {
    await page.goto("/");
  });

  await test.step("2. anchor: The catalog is loaded", async () => {
    await expect(page.getByRole("button", { name: "Add Wireless Mouse to cart" })).toBeVisible({ timeout: 5000 });
  });

  await test.step("3. anchor: The cart badge starts at Cart (0)", async () => {
    await expect(page.getByRole("link", { name: "Cart" })).toHaveText("Cart (0)", { timeout: 5000 });
  });

  await test.step("4. click button \"Add Wireless Mouse to cart\"", async () => {
    await page.getByRole("button", { name: "Add Wireless Mouse to cart" }).click();
  });

  await test.step("5. anchor: The cart badge displays Cart (1) after adding one item", async () => {
    await expect(page.getByRole("link", { name: "Cart" })).toHaveText("Cart (1)", { timeout: 5000 });
  });

  await test.step("6. click button \"Remove Wireless Mouse\"", async () => {
    await page.getByRole("button", { name: "Remove Wireless Mouse" }).click();
  });

  await test.step("7. anchor: The server confirms the cart is empty after the removal", async () => {
    await expect.poll(() => lastResponse(responses, "DELETE", "/api/cart/items/mouse")?.status(), { timeout: 5000 }).toBe(200);
    await expect
      .poll(async () => jsonPointer(await lastResponse(responses, "DELETE", "/api/cart/items/mouse")?.json(), "/itemCount"), { timeout: 5000 })
      .toEqual(0);
  });

  await test.step("8. anchor: The cart list shows it is empty", async () => {
    await expect(page.getByText("Your cart is empty")).toBeVisible({ timeout: 5000 });
  });

  await test.step("9. expect: Cart badge displays \"Cart (0)\" after removing the only item", async () => {
    await expect(page.getByRole("link", { name: "Cart" })).toHaveText("Cart (0)", { timeout: 2000 });
  });
});

/** Most recent response to `method path` observed so far (query string ignored). */
function lastResponse(responses: Response[], method: string | undefined, path: string): Response | undefined {
  for (let i = responses.length - 1; i >= 0; i--) {
    const response = responses[i]!;
    if (method !== undefined && response.request().method() !== method) continue;
    if (new URL(response.url()).pathname === path) return response;
  }
  return undefined;
}

/** Resolves an RFC 6901 JSON Pointer; undefined when the path does not exist. */
function jsonPointer(document: unknown, pointer: string): unknown {
  let current = document;
  for (const raw of pointer === "" ? [] : pointer.slice(1).split("/")) {
    const key = raw.replaceAll("~1", "/").replaceAll("~0", "~");
    if (current === null || typeof current !== "object" || !Object.hasOwn(current, key)) return undefined;
    current = (current as Record<string, unknown>)[key];
  }
  return current;
}
